contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: arrays for _tos and v; msg.sender for calls to c will be this contract
    function run(address[] calldata _tos, uint[] calldata v) public payable {
        require(_tos.length == v.length);
        // observe before-values
        address before_from = c.from();
        address before_caddress = c.caddress();

        bool reverted;
        try c.transfer(_tos, v) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // If call did not revert, it must have returned true and the public storage getters must be unchanged.
        assert(reverted || (before_from == c.from() && before_caddress == c.caddress()));
    }

    receive() external payable {}
}

