contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(address[] calldata tos, uint[] calldata vals) public payable {
        // require matching non-empty arrays to exercise the loop and avoid out-of-bounds
        require(tos.length == vals.length && tos.length > 0);
        // require that each vals[i] is either zero or such that (vals[i]*1e18)/vals[i] == 1e18
        // This mirrors the internal require in C to avoid trivially causing a revert there.
        for (uint i = 0; i < vals.length; i++) {
            require(vals[i] == 0 || ((vals[i] * 1000000000000000000) / vals[i]) == 1000000000000000000);
        }

        bool didRevert;
        bool returnedTrue;
        try c.transfer(tos, vals) returns (bool r) {
            didRevert = false;
            returnedTrue = r;
        } catch {
            didRevert = true;
            returnedTrue = false;
        }

        // General rule: under the preconditions, transfer cannot successfully return false.
        // So either it reverted, or it returned true.
        assert(didRevert || returnedTrue == true);
    }

    receive() external payable {}
}

